// 关卡顺序（从简到难）
const ORDER = ['swing', 'blues', 'bluesscale', 'jazz', 'guidetone', 'keycenter', 'jazzvoicing', 'chordscale', 'melodicminor', 'harmonicminor', 'symmetric', 'morescales', 'substitutions', 'color', 'negharmony', 'lcc'];
export const UNITS = ORDER.map((id) => {
  const unit = ALL.find((u) => u.id === id);
  if (!unit) throw new Error(`unknown unit ${id}`);
  return unit;
});
if (UNITS.length !== ALL.length) throw new Error('every unit must appear in ORDER');
